private sealed record HotJointSubmissionFixture(
    string Generation,
    Dictionary<string, byte[]?> OriginalInputs,
    Dictionary<string, byte[]?> CurrentInputs,
    Dictionary<string, byte[]> AuthoredPublicInputs);

private async Task<HotJointSubmissionFixture> AuthorHotJointSubmissionAfterOriginalAsync(
    FileSystemManager.CanonicalWriteLease lease, PendingTurnSnapshotReadAuthority actualOriginal)
{
    var read = PendingTurnSnapshotReader.ReadCurrent(_fs, lease,
        PendingTurnSnapshotPathSelection.CreateWithObservedOptionalPaths(
            ["game_state/meta/soul_state.json"],
            HotJointInputPaths.Where(path => path != "game_state/meta/soul_state.json")));
    Assert.True(read.Success, DescribeValidationIssues(read.Issues));
    var original = Assert.IsType<PendingTurnSnapshotReadAuthority>(read.Snapshot);
    Assert.Equal(actualOriginal.SessionId, original.SessionId);
    Assert.Equal(actualOriginal.RequestId, original.RequestId);
    Assert.Equal(actualOriginal.SnapshotToken, original.SnapshotToken);
    Assert.Equal(43, original.TurnNumber);
    var originalInputs = new Dictionary<string, byte[]?>(StringComparer.Ordinal);
    foreach (var path in HotJointInputPaths)
    {
        if (original.CoveredLogicalPaths.Contains(path, StringComparer.Ordinal))
            originalInputs.Add(path, original.ReadRequiredBytes(path).ToArray());
        else
        {
            Assert.Contains(path, original.AbsentLogicalPaths);
            originalInputs.Add(path, null);
        }
        Assert.Equal(originalInputs[path], await _fs.ReadFileBytesAsync(lease, path));

    bool requireSignedAbsence,
    ICollection<ValidationIssue> issues,
    out bool selected,
    out bool observedAbsent)
{
    selected = false;
    observedAbsent = false;
    var fileKeys = manifest.Files.Keys
        .Where(key => string.Equals(key, path, StringComparison.OrdinalIgnoreCase))
        .ToArray();
    var hashKeys = manifest.SnapshotFileHashes.Keys
        .Where(key => string.Equals(key, path, StringComparison.OrdinalIgnoreCase))
        .ToArray();
    var fileExact = fileKeys.Count(key => string.Equals(key, path, StringComparison.Ordinal));
    var hashExact = hashKeys.Count(key => string.Equals(key, path, StringComparison.Ordinal));

    if (fileKeys.Any(key => !string.Equals(key, path, StringComparison.Ordinal)) ||
        hashKeys.Any(key => !string.Equals(key, path, StringComparison.Ordinal)))
    {
        Add(
            issues,
            path,
            "pending_turn_snapshot_reader_coverage_case_mismatch",
            "signed snapshot coverage contains a confusable path key");
        return false;
    }

    if (fileExact == 1 && hashExact == 1)
    {
        selected = true;
        return true;
    }

    if (optional && fileExact == 0 && hashExact == 0)
    {
        if (!requireSignedAbsence)
            return true;
        if (manifest.OriginalPathPresenceV1 is not null &&
            manifest.OriginalPathPresenceV1.TryGetValue(path, out var present) &&
            !present)
        {
            observedAbsent = true;
            return true;
        }
        Add(
            issues,
            path,
            "pending_turn_snapshot_reader_absence_unproven",
            "optional logical path is uncovered without authenticated original absence");
        return false;
    }

    Add(
        issues,
        path,
        "pending_turn_snapshot_reader_coverage_missing",

        if (current is not null) throw new InvalidDataException("Joint concurrent command is unsupported: " + path);
        continue;
    }
    if (!original.CoveredLogicalPaths.Contains(path, StringComparer.Ordinal))
    {
        if (current is not null) throw new InvalidDataException("Uncovered joint mechanical input is present: " + path);
        // Refusal-only absence never grants pristine canonical authority.
        continue;
    }
    if (current is null || !JsonNode.DeepEquals(ReadJointMechanicalNode(original.ReadRequiredBytes(path), path),
            ReadJointMechanicalNode(current, path)))
        throw new InvalidDataException("Concurrent joint mechanical input changed: " + path);
}
foreach (var path in new[] { AcceptedMechanicsPlan.WoundCommandPath, WoundAcceptedTurnSnapshotContract.PendingResolutionPath,
    "output/narrative_response.json", LiveTurnPreparationService.TurnRequestPath,
    LiveTurnPreparationService.PendingTurnSnapshotManifestPath, PendingTurnSnapshotAuthority.AuthorityPath })
    before.TryAdd(path, await _fs.ReadFileBytesAsync(lease, path));

var requireSignedAbsenceForMissingOptionalPaths = false;
if (paths is PendingTurnSnapshotPathSelection pathSelection)
{
    foreach (var path in pathSelection.OptionalLogicalPaths)
        optional.Add(path);
    requireSignedAbsenceForMissingOptionalPaths =
        pathSelection.RequireSignedAbsenceForMissingOptionalPaths;
}
var exact = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
var yieldedCount = 0;
foreach (var path in paths)
{
    yieldedCount++;
    if (yieldedCount > MaximumRequiredPaths)
    {
        Add(
            issues,
            LiveTurnPreparationService.PendingTurnSnapshotManifestPath,
            "pending_turn_snapshot_reader_required_paths_invalid",
            $"count>{MaximumRequiredPaths}");
        return PendingTurnSnapshotValidatedPathSelection.Empty;
    }
    if (string.IsNullOrWhiteSpace(path) ||
        !string.Equals(path, path.Trim(), StringComparison.Ordinal) ||
        path.Contains('\\') ||
        !PendingTurnSnapshotAuthority.IsSafeRelativePath(path) ||
        !exact.Add(path))
    {
        Add(
            issues,
            LiveTurnPreparationService.PendingTurnSnapshotManifestPath,
            "pending_turn_snapshot_reader_required_paths_invalid",
            path ?? "null");
        continue;
    }
    result.Add(path);
}
if (result.Count == 0)
{
    Add(
        issues,
        LiveTurnPreparationService.PendingTurnSnapshotManifestPath,
        "pending_turn_snapshot_reader_required_paths_invalid",
        "count=0");
    return PendingTurnSnapshotValidatedPathSelection.Empty;
}
if (requireSignedAbsenceForMissingOptionalPaths)
{
    var observed = PendingTurnSnapshotPathPresenceV1.LogicalPaths
        .ToHashSet(StringComparer.Ordinal);
    foreach (var path in result.Where(optional.Contains))
    {
        if (observed.Contains(path))
            continue;
        Add(
            issues,
            LiveTurnPreparationService.PendingTurnSnapshotManifestPath,
            "pending_turn_snapshot_reader_required_paths_invalid",
            $"observed optional path is outside originalPathPresenceV1: {path}");
    }
    if (issues.Count != 0)
        return PendingTurnSnapshotValidatedPathSelection.Empty;
}
return new PendingTurnSnapshotValidatedPathSelection(
